// Static method for cleaner initialization
MaplatApp.createObject = function (option: any): Promise<MaplatApp> {
  return new Promise((resolve) => {
    const app = new MaplatApp(option);
    app.waitReady.then(() => {
      resolve(app);
    });
  });
};


